-- Migration 006 : import des questions Biologie NS1/NS2 validées une à une par l'utilisateur
-- Source : Mobile/curriculum/questions/biologie/*.json (chapitres 1 à 8)
--   ns1_ch01_aliments_nutriments_ration.json       75
--   ns1_ch02_tube_digestif_digestion.json          67
--   ns1_ch03_maladies_alimentation.json            38
--   ns1_ch04_rein_excretion.json                   59
--   ns1_ch05_cellule_unite_vivant.json             46
--   ns1_ch06_eucaryotes_procaryotes.json           39
--   ns1_ch08_classification_vivant.json            67
--   ns1_ns2_ch07_mitose_meiose.json                55
-- Les questions marquées BASE-* existent déjà en production (corrigées par la migration 005) : non réinsérées.
-- Idempotent : une question déjà présente dans son chapitre (même énoncé) n'est pas réinsérée.

BEGIN;

CREATE TEMP TABLE imp (
    matiere_id INT, chapitre TEXT, ref TEXT, enonce TEXT, choix JSONB,
    bonne TEXT, explication TEXT, complexite TEXT, niveau TEXT
) ON COMMIT DROP;


-- Contrôle : chapitres cibles introuvables (attendu 0)
SELECT COUNT(DISTINCT i.chapitre) AS chapitres_introuvables
FROM imp i
WHERE NOT EXISTS (SELECT 1 FROM chapitres c WHERE c.matiere_id = i.matiere_id AND c.titre = i.chapitre);

-- Code matière canonique déjà utilisé pour la Biologie
CREATE TEMP TABLE mat ON COMMIT DROP AS
SELECT q.v4_mat_canonical AS code
FROM questions q JOIN chapitres c ON c.id = q.chapitre_id
WHERE c.matiere_id = 11 AND q.v4_mat_canonical IS NOT NULL
GROUP BY q.v4_mat_canonical ORDER BY COUNT(*) DESC LIMIT 1;

WITH ins AS (
  SELECT c.id, i.enonce, i.choix, i.bonne, i.explication, i.complexite, i.niveau, (SELECT code FROM mat)
  FROM imp i
  JOIN chapitres c ON c.matiere_id = i.matiere_id AND c.titre = i.chapitre
  WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.chapitre_id = c.id AND q.enonce = i.enonce)
  RETURNING id
)
SELECT COUNT(*) AS questions_inserees FROM ins;

-- Bilan par chapitre
SELECT c.titre, COUNT(q.id) AS nb_questions
FROM chapitres c LEFT JOIN questions q ON q.chapitre_id = c.id
WHERE c.matiere_id = 11 AND c.titre IN (SELECT DISTINCT chapitre FROM imp)
GROUP BY c.titre ORDER BY c.titre;

COMMIT;
