INSERT INTO imp VALUES
(11, 'Aliments, nutriments et ration alimentaire', 'B1-01', 'Substance organique ou minérale que l''organisme peut assimiler directement, sans passer par la digestion.', '["Un nutriment", "Un aliment", "Une enzyme", "Un déchet"]', 'Un nutriment', 'Aliment = ce que l''on mange ; nutriment = ce que l''organisme absorbe après digestion.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-02', 'Quels nutriments sont la principale source d''énergie rapide de l''organisme ?', '["Les glucides", "Les vitamines", "Les sels minéraux", "Les fibres"]', 'Les glucides', 'Les glucides (glucose surtout) sont le carburant rapide des cellules ; vitamines et sels minéraux n''apportent pas d''énergie.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-03', 'Quel nutriment a surtout un rôle bâtisseur (construction et réparation des tissus) ?', '["Les protides", "Les glucides", "Les lipides", "L''eau"]', 'Les protides', 'Les protides (protéines) construisent muscles, peau, enzymes, anticorps.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-04', 'Quelle quantité d''énergie libère 1 g de lipides ?', '["38 kJ (9 kcal)", "17 kJ (4 kcal)", "4 kJ (1 kcal)", "75 kJ (18 kcal)"]', '38 kJ (9 kcal)', 'Les lipides sont les nutriments les plus énergétiques : environ 38 kJ/g, contre 17 kJ/g pour glucides et protides.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-05', 'Quelle quantité d''énergie libère 1 g de glucides ?', '["17 kJ (4 kcal)", "38 kJ (9 kcal)", "29 kJ (7 kcal)", "4 kJ (1 kcal)"]', '17 kJ (4 kcal)', 'Glucides et protides libèrent environ 17 kJ (4 kcal) par gramme.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-06', 'Unité du Système international utilisée pour exprimer l''énergie apportée par les aliments.', '["Le joule", "La calorie", "Le watt", "Le newton"]', 'Le joule', 'Le joule (kJ) est l''unité légale ; la calorie (kcal) reste d''usage courant.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-07', 'Combien de kilojoules vaut environ une kilocalorie (kcal) ?', '["4,18 kJ", "1 kJ", "10 kJ", "0,24 kJ"]', '4,18 kJ', '1 kcal = 4,18 kJ ; inversement 1 kJ ≈ 0,24 kcal.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-08', 'Acide organique qui constitue l''unité de structure des protéines.', '["Un acide aminé", "Un acide gras", "Le glucose", "Un nucléotide"]', 'Un acide aminé', 'Une protéine est une chaîne d''acides aminés (20 types différents).', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-09', 'Comment qualifie-t-on les acides aminés que l''organisme ne sait pas fabriquer et que l''alimentation doit apporter ?', '["Essentiels", "Libres", "Saturés", "Réducteurs"]', 'Essentiels', '8 acides aminés essentiels chez l''adulte (9 chez l''enfant) doivent provenir des aliments.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-10', 'Quel type de glucide est le glucose ?', '["Un glucide simple", "Un glucide complexe", "Un glucide insoluble", "Un glucide protéique"]', 'Un glucide simple', 'Le glucose est un sucre simple (ose), directement absorbable.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-11', 'Réserve glucidique insoluble des végétaux, abondante dans les tubercules (igname, manioc) et les graines.', '["L''amidon", "Le glucose", "Le glycogène", "Le saccharose"]', 'L''amidon', 'L''amidon est un polymère de glucose stocké par les plantes ; le glycogène est la réserve animale.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-12', 'Quel réactif colore l''amidon en bleu-noir ?', '["L''eau iodée", "La liqueur de Fehling", "Le réactif du biuret", "Le nitrate d''argent"]', 'L''eau iodée', 'L''eau iodée (iode) forme avec l''amidon un complexe bleu-noir.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-13', 'Quelle couleur de précipité le glucose donne-t-il avec la liqueur de Fehling chauffée ?', '["Rouge brique", "Bleu-noir", "Violet", "Blanc"]', 'Rouge brique', 'La liqueur de Fehling (bleue) donne à chaud un précipité rouge brique avec les sucres réducteurs comme le glucose.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-14', 'Quel test met en évidence les protéines par une coloration violette ?', '["La réaction du biuret", "L''eau iodée", "La liqueur de Fehling", "Le nitrate d''argent"]', 'La réaction du biuret', 'Le réactif du biuret (soude + sulfate de cuivre) vire au violet en présence de protéines.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-15', 'Quels nutriments révèle une tache translucide persistante sur du papier ?', '["Les lipides", "Les glucides", "Les protides", "Les sels minéraux"]', 'Les lipides', 'Les lipides laissent sur le papier une tache translucide qui ne disparaît pas en séchant (contrairement à l''eau).', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-16', 'Quelle substance révèle un précipité blanc avec le nitrate d''argent ?', '["Les chlorures", "L''amidon", "Les protéines", "Le glucose"]', 'Les chlorures', 'Les ions chlorure (sels minéraux comme NaCl) forment avec le nitrate d''argent un précipité blanc qui noircit à la lumière.', 'Difficile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-17', 'Substance organique indispensable en très petite quantité, que l''organisme ne peut pas fabriquer lui-même.', '["Une vitamine", "Un protide", "Un lipide", "Un glucide"]', 'Une vitamine', 'Les vitamines n''apportent pas d''énergie ; leur manque provoque des maladies de carence.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-18', 'Le manque de quelle substance provoque le scorbut ?', '["La vitamine C", "La vitamine D", "Le fer", "L''iode"]', 'La vitamine C', 'Le scorbut (hémorragies, affaiblissement) est dû au manque de vitamine C (agrumes, fruits frais).', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-19', 'Le manque de quelle vitamine provoque le rachitisme chez l''enfant ?', '["La vitamine D", "La vitamine C", "La vitamine A", "La vitamine B1"]', 'La vitamine D', 'La vitamine D permet la minéralisation des os ; sa carence déforme le squelette.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-20', 'Quel trouble provoque surtout une carence en vitamine A ?', '["Des troubles de la vision", "Un saignement des gencives", "Une déformation des os", "Un goitre"]', 'Des troubles de la vision', 'La vitamine A est nécessaire à la vision (cécité nocturne, xérophtalmie en cas de carence).', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-21', 'Le manque de quelle substance provoque le béribéri ?', '["La vitamine B1", "La vitamine C", "La vitamine K", "Le calcium"]', 'La vitamine B1', 'Le béribéri (troubles cardiaques ou neurologiques) est lié au manque de vitamine B1, fréquent avec le riz très décortiqué.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-22', 'Quelle maladie provoque une carence en fer ?', '["L''anémie", "Le goitre", "Le scorbut", "Le rachitisme"]', 'L''anémie', 'Le fer entre dans l''hémoglobine ; son manque en diminue le taux (anémie) et réduit le transport d''oxygène.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-23', 'Quelle maladie provoque une carence en iode ?', '["Le goitre", "L''anémie", "Le béribéri", "Le scorbut"]', 'Le goitre', 'L''iode est nécessaire aux hormones thyroïdiennes ; son manque fait grossir la thyroïde (goitre). D''où le sel iodé.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-24', 'Quel sel minéral est indispensable à la solidité des os et des dents ?', '["Le calcium", "Le sodium", "Le fer", "L''iode"]', 'Le calcium', 'Le calcium (lait, poissons à arêtes) minéralise os et dents.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-25', 'Malnutrition de l''enfant due à une alimentation pauvre en protéines, même si l''énergie apportée suffit.', '["Le kwashiorkor", "Le marasme", "Le rachitisme", "Le béribéri"]', 'Le kwashiorkor', 'Ventre gonflé et œdèmes sont typiques du kwashiorkor, souvent après le sevrage.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-26', 'État pathologique dû à un apport énergétique insuffisant.', '["Le marasme", "Le kwashiorkor", "Le scorbut", "Le goitre"]', 'Le marasme', 'Le marasme se traduit par une maigreur extrême (fonte des muscles et des graisses).', 'Difficile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-27', 'Principal constituant du corps humain, environ 60 % de sa masse.', '["L''eau", "Les protides", "Les lipides", "Le calcium"]', 'L''eau', 'L''eau représente environ 60 % de la masse d''un adulte ; elle doit être renouvelée chaque jour.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-28', 'Quel est le rôle principal des fibres alimentaires ?', '["Faciliter le transit intestinal", "Apporter beaucoup d''énergie", "Construire les muscles", "Transporter le dioxygène"]', 'Faciliter le transit intestinal', 'Non digérées, les fibres (légumes, fruits, céréales complètes) facilitent le transit et préviennent la constipation.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-29', 'Quelle est la formule de l''indice de masse corporelle (IMC) ?', '["Masse ÷ taille²", "Taille ÷ masse", "Masse × taille", "Masse ÷ âge"]', 'Masse ÷ taille²', 'IMC = masse (kg) ÷ taille² (m²), exprimé en kg/m².', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-30', 'Quel est l''IMC d''un adulte de 81 kg mesurant 1,80 m ?', '["25", "45", "20", "30"]', '25', '81 ÷ (1,80 × 1,80) = 81 ÷ 3,24 = 25 kg/m².', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-31', 'Selon l''OMS, entre quelles valeurs se situe l''IMC d''un adulte de corpulence normale ?', '["18,5 et 24,9", "25 et 29,9", "16 et 18,4", "30 et 34,9"]', '18,5 et 24,9', 'OMS : < 18,5 maigreur ; 18,5–24,9 normal ; 25–29,9 surpoids ; ≥ 30 obésité.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-32', 'Selon l''OMS, à partir de quel IMC un adulte est-il obèse ?', '["30", "25", "18,5", "24,9"]', '30', 'L''obésité commence à un IMC de 30 kg/m² ; entre 25 et 29,9, on parle de surpoids.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-33', 'Comment qualifie-t-on une ration qui couvre tous les besoins de l''organisme, en qualité et en quantité ?', '["Équilibrée", "Restrictive", "Carencée", "Excédentaire"]', 'Équilibrée', 'Elle apporte assez d''énergie et tous les nutriments grâce à la variété des groupes d''aliments.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-34', 'Quelle part de l''énergie les glucides fournissent-ils dans une ration équilibrée ?', '["50 à 55 %", "10 à 15 %", "30 à 35 %", "80 à 90 %"]', '50 à 55 %', 'Répartition classique : glucides 50–55 %, lipides 30–35 %, protides 12–15 % de l''apport énergétique.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-35', 'Quelle part de l''énergie les protides fournissent-ils dans une ration équilibrée ?', '["12 à 15 %", "50 à 55 %", "30 à 35 %", "1 à 2 %"]', '12 à 15 %', 'Les protides couvrent 12 à 15 % de l''énergie ; leur rôle principal reste la construction.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-36', 'Dans quelles conditions mesure-t-on le métabolisme de base ?', '["Au repos complet, à jeun", "Pendant un effort intense", "Pendant la digestion", "Pendant la croissance"]', 'Au repos complet, à jeun', 'Il couvre les fonctions vitales (cœur, respiration, température) ; s''y ajoutent les dépenses d''activité.', 'Difficile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-37', 'De quoi dépendent les besoins énergétiques d''une personne ?', '["De l''âge, du sexe, de l''activité", "Du groupe sanguin seul", "De la couleur des yeux", "Du mois de naissance"]', 'De l''âge, du sexe, de l''activité', 'Âge, sexe, activité physique et état (croissance, grossesse) modifient les besoins.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-39', 'À quel groupe d''aliments appartiennent le riz, le maïs, le pain et la banane plantain ?', '["Céréales et féculents", "Produits laitiers", "Viandes et poissons", "Matières grasses"]', 'Céréales et féculents', 'Les céréales et féculents sont riches en amidon : ils fournissent l''énergie de base.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-40', 'Quels nutriments le lait et le fromage apportent-ils surtout ?', '["Calcium et protides", "Fer et glucides", "Vitamine C et fibres", "Iode et lipides"]', 'Calcium et protides', 'Les produits laitiers apportent calcium et protéines de bonne qualité.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-41', 'À quelle famille de plantes appartiennent les pois (haricots), riches en protéines végétales ?', '["Les légumineuses", "Les céréales", "Les tubercules", "Les fruits secs sucrés"]', 'Les légumineuses', 'Les légumineuses (pois, lentilles, arachide) complètent bien les céréales comme le riz (« diri ak pwa »).', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-42', 'Quand une ration est-elle déséquilibrée sur le plan qualitatif ?', '["Quand un groupe d''aliments manque", "Quand l''énergie apportée est trop forte", "Quand les repas sont trop espacés", "Quand on boit moins de deux litres"]', 'Quand un groupe d''aliments manque', 'Qualitatif = variété des nutriments ; quantitatif = quantité d''énergie apportée.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-43', 'À quelle molécule les acides gras sont-ils reliés dans une molécule de lipide (graisse) ?', '["Au glycérol", "Au glucose", "Aux acides aminés", "À l''amidon"]', 'Au glycérol', 'Un triglycéride = 1 glycérol + 3 acides gras ; la digestion les sépare.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-44', 'Pour quelle durée calcule-t-on une ration alimentaire ?', '["Une journée", "Un seul repas", "Une semaine", "Une heure"]', 'Une journée', 'La ration se calcule sur 24 heures ; elle se répartit ensuite entre les repas.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-45', 'Composant de la matière vivante formé d''acides gras, présent dans les structures cellulaires et au rôle énergétique.', '["Un lipide", "Un glucide", "Un protide", "Une vitamine"]', 'Un lipide', 'Graisses et huiles sont des lipides ; ils fournissent 38 kJ par gramme.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-46', 'Substance formée d''un ou de plusieurs acides aminés, comme les peptides et les protéines.', '["Un protide", "Un lipide", "Un glucide", "Un sel minéral"]', 'Un protide', '« Protide » regroupe peptides et protéines (rôle bâtisseur).', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-47', 'Quels nutriments les viandes, poissons et œufs apportent-ils surtout ?', '["Protides et fer", "Glucides et fibres", "Vitamine C et eau", "Calcium et amidon"]', 'Protides et fer', 'Ce groupe apporte des protéines de bonne qualité et du fer.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-48', 'Qu''apportent surtout les fruits et légumes frais ?', '["Vitamines, minéraux, fibres", "Lipides et protides", "Amidon et protides", "Cholestérol et sucres"]', 'Vitamines, minéraux, fibres', 'Ils sont peu énergétiques mais riches en vitamines (C notamment), sels minéraux, fibres et eau.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-49', 'À quel groupe d''aliments appartiennent l''huile, le beurre et le saindoux ?', '["Matières grasses", "Produits sucrés", "Produits laitiers", "Céréales et féculents"]', 'Matières grasses', 'Les matières grasses sont surtout des lipides : très énergétiques, à consommer avec modération.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-50', 'Pourquoi est-il intéressant d''associer le riz et les pois dans un même repas ?', '["Leurs protéines se complètent", "Ils apportent la vitamine C", "Ils remplacent le lait", "Ils réduisent l''énergie"]', 'Leurs protéines se complètent', 'Céréales et légumineuses manquent d''acides aminés essentiels différents : ensemble, elles apportent des protéines complètes.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-51', 'Quelle part de l''énergie les lipides fournissent-ils dans une ration équilibrée ?', '["30 à 35 %", "50 à 55 %", "12 à 15 %", "70 à 80 %"]', '30 à 35 %', 'Répartition classique : glucides 50–55 %, lipides 30–35 %, protides 12–15 %.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-52', 'Absence ou manque d''un élément indispensable à l''organisme, par exemple en vitamines.', '["Une carence", "Un excès", "Une allergie", "Une intoxication"]', 'Une carence', 'Une carence prolongée provoque une maladie de carence (scorbut, rachitisme…).', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-53', 'Insuffisance de la quantité d''aliments consommés, assez prolongée pour provoquer des troubles.', '["La sous-alimentation", "La suralimentation", "La déshydratation", "L''indigestion"]', 'La sous-alimentation', 'La sous-alimentation est un manque en quantité ; le contraire est la suralimentation.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-54', 'État nutritionnel anormal dû à une alimentation mal équilibrée en quantité ou en qualité.', '["La malnutrition", "La digestion", "La déshydratation", "L''indigestion"]', 'La malnutrition', 'La malnutrition regroupe la sous-alimentation, la suralimentation et la mauvaise assimilation.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-55', 'Glucide formé de longues chaînes ramifiées de glucose, principale réserve de glucose de l''organisme.', '["Le glycogène", "L''amidon", "La cellulose", "Le saccharose"]', 'Le glycogène', 'Le glycogène est stocké dans le foie et les muscles ; l''amidon est la réserve des végétaux.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-56', 'Nom scientifique du sucre de canne, formé d''une molécule de glucose et d''une de fructose.', '["Le saccharose", "Le lactose", "L''amidon", "Le glycogène"]', 'Le saccharose', 'Le saccharose est le sucre de table, extrait en Haïti de la canne à sucre.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-57', 'Sucre contenu dans le lait, formé de glucose et de galactose.', '["Le lactose", "Le saccharose", "Le glycogène", "La cellulose"]', 'Le lactose', 'La digestion du lactose libère du glucose et du galactose.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-58', 'Glucide macromoléculaire qui constitue la paroi des cellules végétales.', '["La cellulose", "L''amidon", "Le glycogène", "Le lactose"]', 'La cellulose', 'Non digérée par l''être humain, la cellulose forme l''essentiel des fibres alimentaires.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-59', 'Stérol d''origine alimentaire ou fabriqué par l''organisme, qui peut se déposer sur la paroi des artères.', '["Le cholestérol", "Le glycérol", "Le glycogène", "L''amidon"]', 'Le cholestérol', 'En excès, le cholestérol favorise l''athérosclérose et les maladies cardiovasculaires.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-60', 'Quelles vitamines sont solubles dans les graisses (liposolubles) ?', '["A, D, E et K", "B et C", "C seulement", "B1 et B12"]', 'A, D, E et K', 'Les vitamines A, D, E, K sont liposolubles ; les vitamines B et C sont hydrosolubles (solubles dans l''eau).', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-61', 'Dans quel phénomène la vitamine K intervient-elle surtout ?', '["La coagulation du sang", "La vision nocturne", "La fixation du calcium", "La croissance des cheveux"]', 'La coagulation du sang', 'La vitamine K (légumes verts) est nécessaire à la coagulation sanguine.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-62', 'En dehors de l''alimentation, comment l''organisme obtient-il de la vitamine D ?', '["Par l''exposition au soleil", "En buvant de l''eau", "Par le sommeil", "Par l''effort physique"]', 'Par l''exposition au soleil', 'Les rayons ultraviolets du soleil permettent à la peau de fabriquer de la vitamine D.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-63', 'Comment appelle-t-on les sels minéraux nécessaires en quantité infime, comme le fer, l''iode ou le zinc ?', '["Des oligoéléments", "Des macroéléments", "Des vitamines", "Des nutriments énergétiques"]', 'Des oligoéléments', 'Calcium, sodium, potassium sont nécessaires en plus grande quantité ; fer, iode, zinc sont des oligoéléments.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-64', 'Quel est le rôle principal des vitamines et des sels minéraux dans l''organisme ?', '["Un rôle fonctionnel (protecteur)", "Un rôle énergétique", "Un rôle de réserve", "Aucun rôle utile"]', 'Un rôle fonctionnel (protecteur)', 'Ils règlent le fonctionnement de l''organisme ; seul le calcium a aussi un rôle bâtisseur marqué.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-66', 'À quelle maladie conduit une ration qui apporte régulièrement trop d''énergie ?', '["L''obésité", "Le scorbut", "Le rachitisme", "Le béribéri"]', 'L''obésité', 'Un excès d''énergie (déséquilibre quantitatif) est stocké sous forme de graisse.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-67', 'Selon l''OMS, dans quelle situation est un adulte dont l''IMC est inférieur à 18,5 ?', '["La maigreur", "Le surpoids", "L''obésité", "La corpulence normale"]', 'La maigreur', 'Moins de 18,5 : maigreur (insuffisance pondérale).', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-68', 'Selon l''OMS, à quoi correspond un IMC compris entre 25 et 29,9 ?', '["Au surpoids", "À l''obésité", "À la maigreur", "À une corpulence normale"]', 'Au surpoids', '25 à 29,9 : surpoids ; 30 ou plus : obésité.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-71', 'Quelle quantité d''eau un adulte doit-il renouveler environ chaque jour (boissons et aliments) ?', '["Environ 2,5 litres", "Environ 0,5 litre", "Environ 10 litres", "Environ 25 litres"]', 'Environ 2,5 litres', 'L''organisme perd environ 2,5 L d''eau par jour (urine, sueur, respiration) ; boissons et aliments compensent.', 'Difficile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-72', 'Lipide formé de trois molécules d''acide gras reliées à une molécule de glycérol.', '["Un triglycéride", "Un peptide", "Un glucide", "Un acide aminé"]', 'Un triglycéride', 'C''est la forme principale des graisses alimentaires et des réserves du tissu adipeux.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-73', 'Substance formée d''au moins deux acides aminés.', '["Un peptide", "Un triglycéride", "Un glucide", "Un nucléotide"]', 'Un peptide', 'Une protéine est une très longue chaîne d''acides aminés ; un peptide, une chaîne plus courte.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-74', 'Pigment protéique des globules rouges, qui transporte le dioxygène dans le sang.', '["L''hémoglobine", "La chlorophylle", "La mélanine", "La bile"]', 'L''hémoglobine', 'Le fer est indispensable à sa fabrication : d''où l''anémie en cas de carence en fer.', 'Moyen', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-75', 'Sécheresse de l''œil pouvant aller jusqu''à la cécité, liée notamment au manque de vitamine A.', '["La xérophtalmie", "Le goitre", "Le scorbut", "Le rachitisme"]', 'La xérophtalmie', 'La vitamine A se trouve dans le foie, le lait, la carotte, la mangue, la patate douce orange.', 'Difficile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-76', 'Élément chimique nécessaire à la fabrication des hormones de la glande thyroïde.', '["L''iode", "Le fer", "Le calcium", "Le sodium"]', 'L''iode', 'Son manque provoque le goitre ; on le trouve dans le sel iodé et les produits de la mer.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-77', 'Plante cultivée pour ses grains, qui servent à nourrir l''homme et les animaux, comme le riz ou le maïs.', '["Une céréale", "Une légumineuse", "Un tubercule", "Un fruit"]', 'Une céréale', 'Riz, maïs, mil (petit mil), blé et sorgho sont des céréales.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-78', 'Renflement souterrain d''une plante, riche en réserves, comme l''igname ou le manioc.', '["Un tubercule", "Une céréale", "Une gousse", "Une feuille"]', 'Un tubercule', 'Igname, manioc, patate douce et pomme de terre sont des tubercules riches en amidon.', 'Facile', 'NS1'),
(11, 'Aliments, nutriments et ration alimentaire', 'B1-79', 'Partie de la médecine qui adapte le régime alimentaire aux besoins de chaque personne.', '["La diététique", "La gastronomie", "La pharmacie", "La chirurgie"]', 'La diététique', 'Le diététicien établit des rations adaptées (diabète, obésité, grossesse…).', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-01', 'Ensemble des transformations qui changent les aliments en nutriments dans le tube digestif.', '["La digestion", "L''absorption", "La déglutition", "La mastication"]', 'La digestion', 'La digestion rend les aliments assez petits pour traverser la paroi intestinale.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-02', 'Protéine qui accélère les réactions chimiques de l''organisme.', '["Une enzyme", "Une hormone", "Une vitamine", "Un anticorps"]', 'Une enzyme', 'Les enzymes digestives (amylase, pepsine, lipase…) découpent les grosses molécules des aliments.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-03', 'Action de broyer les aliments avec les dents, considérée comme la première étape de la digestion.', '["La mastication", "La déglutition", "L''ingestion", "L''absorption"]', 'La mastication', 'La mastication est une digestion mécanique ; elle mélange aussi les aliments à la salive.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-04', 'Acte par lequel le bol alimentaire passe de la bouche dans l''œsophage, puis dans l''estomac.', '["La déglutition", "La mastication", "L''absorption", "Le péristaltisme"]', 'La déglutition', 'Avaler = déglutir. L''épiglotte ferme alors le larynx pour éviter la « fausse route ».', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-05', 'Action d''avaler des aliments, qui les fait entrer dans le tube digestif.', '["L''ingestion", "La digestion", "L''absorption", "L''excrétion"]', 'L''ingestion', 'L''ingestion est l''entrée des aliments dans le tube digestif.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-06', 'Liquide clair et filant, sécrété par des glandes de la bouche, qui facilite la déglutition.', '["La salive", "La bile", "Le suc gastrique", "Le suc pancréatique"]', 'La salive', 'Produite par les glandes salivaires, la salive contient aussi l''amylase salivaire.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-07', 'Conduit musculaire où se croisent la voie digestive et la voie respiratoire.', '["Le pharynx", "Le larynx", "L''œsophage", "La trachée"]', 'Le pharynx', 'Le pharynx (gorge) mène à la fois vers l''œsophage et vers le larynx.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-08', 'Partie du tube digestif allant du pharynx à l''estomac, dont les mouvements font descendre le bol alimentaire.', '["L''œsophage", "Le duodénum", "Le côlon", "Le pylore"]', 'L''œsophage', 'L''œsophage ne digère pas : il transporte le bol alimentaire par péristaltisme.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-09', 'Partie du tube digestif située sous le diaphragme, où les aliments sont stockés, brassés et prédigérés.', '["L''estomac", "Le duodénum", "Le rectum", "Le pharynx"]', 'L''estomac', 'L''estomac brasse les aliments avec le suc gastrique, acide, qui les stérilise aussi.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-10', 'Orifice inférieur de l''estomac, qui le fait communiquer avec le duodénum.', '["Le pylore", "Le cardia", "L''anus", "L''épiglotte"]', 'Le pylore', 'Le pylore (sphincter) laisse passer le chyme par petites quantités ; le cardia est l''orifice supérieur.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-11', 'Produit de la digestion du bol alimentaire dans l''estomac, au moment où il arrive dans le duodénum.', '["Le chyme", "Le chyle", "La bile", "La salive"]', 'Le chyme', 'Bol alimentaire (bouche) → chyme (sortie de l''estomac).', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-12', 'Partie initiale de l''intestin grêle, qui fait suite au pylore.', '["Le duodénum", "Le jéjunum", "L''iléon", "Le côlon"]', 'Le duodénum', 'Le duodénum reçoit la bile et le suc pancréatique.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-13', 'Partie de l''intestin comprise entre la fin de l''intestin grêle et le rectum, qui élabore les matières fécales.', '["Le côlon", "Le duodénum", "L''œsophage", "L''iléon"]', 'Le côlon', 'Le côlon (gros intestin) réabsorbe l''eau et forme les selles.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-14', 'Segment terminal du tube digestif, qui fait suite au côlon et s''ouvre à l''extérieur.', '["Le rectum", "Le cæcum", "Le duodénum", "Le pylore"]', 'Le rectum', 'Le rectum stocke les matières fécales avant leur évacuation par l''anus.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-15', 'Orifice extérieur du rectum, par lequel sont évacuées les matières fécales.', '["L''anus", "Le pylore", "Le cardia", "Le méat"]', 'L''anus', 'L''anus est la fin du tube digestif.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-16', 'Ensemble des contractions musculaires d''un organe creux qui font progresser son contenu.', '["Le péristaltisme", "La déglutition", "La mastication", "La digestion"]', 'Le péristaltisme', 'Le péristaltisme fait avancer les aliments tout le long du tube digestif.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-17', 'Chacune des petites saillies qui tapissent l''intérieur de l''intestin grêle et lui donnent un aspect velu.', '["Une villosité", "Une papille", "Une alvéole", "Un sphincter"]', 'Une villosité', 'Les villosités augmentent énormément la surface d''absorption de l''intestin grêle.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-18', 'Liquide amer, jaune d''or verdissant à l''air, sécrété par le foie, qui contribue à la digestion.', '["La bile", "La salive", "Le suc pancréatique", "Le suc gastrique"]', 'La bile', 'La bile est stockée dans la vésicule biliaire puis versée dans le duodénum.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-19', 'Volumineuse glande annexe du tube digestif, aux fonctions multiples de synthèse et de transformation.', '["Le foie", "Le pancréas", "La rate", "L''estomac"]', 'Le foie', 'Le foie fabrique la bile, stocke le glycogène et transforme de nombreuses substances.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-20', 'Organe glandulaire situé sous et derrière l''estomac, qui sécrète un suc digestif et l''insuline.', '["Le pancréas", "Le foie", "La rate", "La vésicule biliaire"]', 'Le pancréas', 'Le pancréas est à la fois glande digestive (suc pancréatique) et glande hormonale (insuline, glucagon).', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-21', 'Enzyme d''origine salivaire ou pancréatique qui dégrade l''amidon en maltose.', '["L''amylase", "La pepsine", "La lipase", "La trypsine"]', 'L''amylase', 'Le maltose est ensuite coupé en glucose dans l''intestin grêle.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-22', 'Enzyme de l''estomac qui dégrade les protéines des aliments.', '["La pepsine", "L''amylase", "La lipase", "La maltase"]', 'La pepsine', 'La pepsine agit en milieu très acide ; elle commence la digestion des protéines.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-23', 'Enzyme qui hydrolyse les lipides en libérant des acides gras.', '["La lipase", "L''amylase", "La pepsine", "La maltase"]', 'La lipase', 'La lipase pancréatique agit dans l''intestin grêle, aidée par la bile.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-24', 'Destruction d''une substance chimique par l''eau.', '["L''hydrolyse", "L''oxydation", "La fermentation", "La combustion"]', 'L''hydrolyse', 'Les enzymes digestives réalisent des hydrolyses : elles coupent les molécules en fixant de l''eau.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-25', 'Organe ou tissu qui sécrète une substance, puis l''excrète.', '["Une glande", "Un muscle", "Un tendon", "Un nerf"]', 'Une glande', 'Glandes salivaires, gastriques, foie et pancréas sont des glandes digestives.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-26', 'Liquide organique produit par sécrétion et contenant des enzymes.', '["Un suc", "Une hormone", "Le plasma", "La lymphe"]', 'Un suc', 'Suc gastrique, suc pancréatique, suc intestinal.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-27', 'Pénétration de liquides ou de substances dans un organisme vivant à travers une paroi perméable.', '["L''absorption", "La digestion", "L''excrétion", "La déglutition"]', 'L''absorption', 'L''absorption intestinale fait passer les nutriments dans le sang et la lymphe.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-28', 'Transformation par l''organisme de molécules différentes des siennes pour les rendre identiques à ses propres constituants.', '["L''assimilation", "L''absorption", "L''excrétion", "La respiration"]', 'L''assimilation', 'Après l''absorption, les nutriments sont assimilés : ils servent à construire les tissus de l''organisme.', 'Difficile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-29', 'Liquide riche en lipides issus de la digestion, qui circule dans les vaisseaux lymphatiques de l''intestin grêle.', '["Le chyle", "Le chyme", "La bile", "La salive"]', 'Le chyle', 'Ne pas confondre : chyme (sortie de l''estomac) et chyle (lymphe chargée de lipides).', 'Difficile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-30', 'Dispersion d''un liquide, sous forme de fins globules, dans un autre liquide.', '["Une émulsion", "Une solution", "Un précipité", "Une hydrolyse"]', 'Une émulsion', 'La bile émulsionne les graisses, ce qui facilite l''action de la lipase.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-31', 'Dent aplatie et tranchante, située à l''avant de la mâchoire, qui sert à couper les aliments.', '["Une incisive", "Une canine", "Une prémolaire", "Une molaire"]', 'Une incisive', '4 incisives par mâchoire chez l''adulte.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-32', 'Dent située entre les incisives et les prémolaires, qui peut s''allonger en croc chez certains animaux.', '["Une canine", "Une incisive", "Une prémolaire", "Une molaire"]', 'Une canine', 'Les canines servent à déchirer les aliments.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-33', 'Dent située entre les canines et les molaires, qui sert à écraser les aliments.', '["Une prémolaire", "Une incisive", "Une canine", "Une dent de sagesse"]', 'Une prémolaire', '4 prémolaires par mâchoire chez l''adulte.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-34', 'Opération qui consiste à séparer méthodiquement les différentes parties d''un organisme.', '["La dissection", "La digestion", "La mastication", "La fermentation"]', 'La dissection', 'La dissection d''un vertébré (souris, lapin, poisson) permet d''observer le tube digestif.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-35', 'Dans quel ordre les aliments traversent-ils le tube digestif ?', '["Bouche, œsophage, estomac, intestin", "Bouche, estomac, œsophage, intestin", "Bouche, intestin, estomac, œsophage", "Œsophage, bouche, estomac, intestin"]', 'Bouche, œsophage, estomac, intestin', 'Puis gros intestin (côlon), rectum et anus.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-36', 'Quelles sont, dans l''ordre, les trois parties de l''intestin grêle ?', '["Duodénum, jéjunum, iléon", "Jéjunum, duodénum, iléon", "Iléon, jéjunum, duodénum", "Duodénum, iléon, jéjunum"]', 'Duodénum, jéjunum, iléon', 'L''intestin grêle mesure 6 à 7 m chez l''adulte.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-37', 'Où se fait l''essentiel de l''absorption des nutriments ?', '["Dans l''intestin grêle", "Dans l''estomac", "Dans le gros intestin", "Dans l''œsophage"]', 'Dans l''intestin grêle', 'Grâce à ses villosités, l''intestin grêle offre une très grande surface d''échange.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-38', 'Quel acide rend le suc gastrique très acide ?', '["L''acide chlorhydrique", "L''acide citrique", "L''acide lactique", "L''acide acétique"]', 'L''acide chlorhydrique', 'L''acide chlorhydrique active la pepsine et tue une grande partie des microbes.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-39', 'Comment la bile, qui ne contient pas d''enzyme, agit-elle sur les lipides ?', '["En les émulsionnant", "En les hydrolysant", "En les absorbant", "En les oxydant"]', 'En les émulsionnant', 'Elle fractionne les graisses en fines gouttelettes : la lipase agit alors plus vite.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-41', 'Dans quelle partie du tube digestif le suc pancréatique est-il déversé ?', '["Le duodénum", "L''estomac", "Le côlon", "L''œsophage"]', 'Le duodénum', 'Bile et suc pancréatique arrivent ensemble dans le duodénum.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-42', 'Quelle enzyme du suc pancréatique poursuit la digestion des protéines ?', '["La trypsine", "L''amylase", "La lipase", "La maltase"]', 'La trypsine', 'Pepsine (estomac) puis trypsine (intestin) découpent les protéines.', 'Difficile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-43', 'Quel est le produit final de la digestion de l''amidon ?', '["Le glucose", "Le glycérol", "Les acides aminés", "Les acides gras"]', 'Le glucose', 'Amidon → maltose (amylase) → glucose (maltase).', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-44', 'Quels sont les produits finaux de la digestion des protides ?', '["Les acides aminés", "Les acides gras", "Le glucose", "Le glycérol"]', 'Les acides aminés', 'Les acides aminés sont absorbés et passent dans le sang.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-45', 'Quels sont les produits finaux de la digestion des lipides ?', '["Acides gras et glycérol", "Glucose et fructose", "Acides aminés", "Maltose et lactose"]', 'Acides gras et glycérol', 'La lipase coupe les triglycérides en acides gras et glycérol.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-46', 'À quelle température l''amylase salivaire agit-elle le mieux ?', '["Environ 37 °C", "Environ 0 °C", "Environ 70 °C", "Environ 100 °C"]', 'Environ 37 °C', 'C''est la température du corps ; une forte chaleur détruit l''enzyme, le froid la ralentit.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-47', 'Que réabsorbe surtout l''organisme dans le gros intestin ?', '["L''eau", "Le glucose", "Les acides aminés", "Les lipides"]', 'L''eau', 'La réabsorption de l''eau donne leur consistance aux matières fécales.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-48', 'Combien de dents compte la denture définitive d''un adulte ?', '["32", "20", "28", "36"]', '32', '8 incisives, 4 canines, 8 prémolaires, 12 molaires (dont les dents de sagesse).', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-49', 'Combien de dents compte la denture de lait d''un enfant ?', '["20", "32", "24", "16"]', '20', 'La denture de lait n''a pas de prémolaires.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-50', 'Comment s''appellent les dents larges du fond de la bouche, qui broient les aliments ?', '["Les molaires", "Les incisives", "Les canines", "Les prémolaires"]', 'Les molaires', 'Les molaires ont une large surface à plusieurs pointes (cuspides).', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-51', 'Quelles sont les glandes annexes du tube digestif ?', '["Glandes salivaires, foie, pancréas", "Thyroïde, hypophyse, surrénales", "Reins, vessie, uretères", "Cœur, poumons, rate"]', 'Glandes salivaires, foie, pancréas', 'Elles déversent leurs sécrétions dans le tube digestif par des canaux.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-52', 'Que comprend la digestion mécanique ?', '["La mastication et le brassage", "L''action des enzymes", "L''absorption intestinale", "L''hydrolyse des protéines"]', 'La mastication et le brassage', 'Digestion mécanique = fragmentation ; digestion chimique = action des enzymes.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-53', 'Qu''augmentent les villosités intestinales ?', '["La surface d''absorption", "La vitesse de mastication", "L''acidité gastrique", "La production de bile"]', 'La surface d''absorption', 'La surface d''absorption de l''intestin grêle atteint environ 200 m².', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-54', 'Dans quoi passent les nutriments après l''absorption ?', '["Le sang et la lymphe", "L''air des poumons", "L''urine", "La bile"]', 'Le sang et la lymphe', 'Glucose et acides aminés vont dans le sang ; une grande partie des lipides passe dans la lymphe.', 'Facile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-55', 'Languette de cartilage qui ferme l''entrée du larynx au moment de la déglutition.', '["L''épiglotte", "La luette", "Le pylore", "Le cardia"]', 'L''épiglotte', 'Elle empêche les aliments de passer dans les voies respiratoires (« fausse route »).', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-56', 'Petit appendice charnu au fond du palais, qui ferme les fosses nasales pendant la déglutition.', '["La luette", "L''épiglotte", "La langue", "Le pharynx"]', 'La luette', 'Elle empêche les aliments de remonter vers le nez.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-57', 'Zone de passage entre l''œsophage et l''estomac.', '["Le cardia", "Le pylore", "Le duodénum", "Le pharynx"]', 'Le cardia', 'Cardia = entrée de l''estomac ; pylore = sortie de l''estomac.', 'Difficile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-58', 'Partie de l''intestin grêle comprise entre le duodénum et l''iléon.', '["Le jéjunum", "Le cæcum", "Le côlon", "Le rectum"]', 'Le jéjunum', 'C''est la deuxième portion de l''intestin grêle.', 'Difficile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-59', 'Partie terminale de l''intestin grêle, qui précède le début du gros intestin.', '["L''iléon", "Le jéjunum", "Le duodénum", "Le côlon"]', 'L''iléon', 'L''iléon débouche dans le cæcum.', 'Difficile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-60', 'Partie initiale du gros intestin, qui porte l''appendice.', '["Le cæcum", "Le duodénum", "Le rectum", "L''iléon"]', 'Le cæcum', 'L''inflammation de l''appendice s''appelle l''appendicite.', 'Difficile', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-61', 'Sucre formé lors de la digestion incomplète de l''amidon, qui donne ensuite deux molécules de glucose.', '["Le maltose", "Le lactose", "Le saccharose", "Le glycogène"]', 'Le maltose', 'Amidon → maltose (amylase) → glucose.', 'Moyen', 'NS1'),
(11, 'Le tube digestif et la digestion', 'B2-62', 'Enzyme du suc intestinal qui achève la digestion de l''amidon en libérant du glucose.', '["La maltase", "L''amylase", "La trypsine", "La pepsine"]', 'La maltase', 'L''amylase s''arrête au maltose ; la maltase le coupe en deux glucoses.', 'Difficile', 'NS1'),
